import React from 'react';
import ImageUploader from './ImageUpLoader';

const AddCar = () => {
  return (
    <div className="max-w-7xl mx-auto bg-white p-8 rounded-lg shadow">
      <h1 className="text-2xl font-bold mb-6 text-gray-800">Submit Listing</h1>

      <form className="space-y-6">
        {/* Блок с полями */}
        <div className="grid grid-cols-4 gap-4">
          {[
            'Brand', 'Model', 'Engine Type', 'Category',
            'Horse power', 'Eurostandart', 'Gearbox', 'Condition',
            'Volume', 'Price', 'Currency', 'Mileage',
            'Year of manufacture', 'Color', 'Country', 'City',
            'Vin Number',
          ].map((label, index) => (
            <div key={index}>
              <label className="block text-sm text-gray-700 mb-1">{label}</label>
              <input
                type="text"
                placeholder={label}
                className="w-full bg-purple-100 border border-gray-300 rounded px-3 py-2 focus:outline-none focus:ring-2 focus:ring-purple-500"
              />
            </div>
          ))}
        </div>

        <ImageUploader></ImageUploader>

        {/* Кнопка отправки */}
        <div className="text-center">
          <button
            type="submit"
            className="bg-purple-700 text-white py-2 px-6 rounded hover:bg-purple-800 transition"
          >
            Submit
          </button>
        </div>
      </form>
    </div>
  );
};

const UploadIcon = ({ small = false }) => (
  <svg
    xmlns="http://www.w3.org/2000/svg"
    className={small ? 'h-6 w-6 text-purple-600' : 'h-10 w-10 text-purple-600'}
    fill="none"
    viewBox="0 0 24 24"
    stroke="currentColor"
    strokeWidth={2}
  >
    <path
      strokeLinecap="round"
      strokeLinejoin="round"
      d="M4 16v2a2 2 0 002 2h12a2 2 0 002-2v-2M7 10l5-5m0 0l5 5m-5-5v12"
    />
  </svg>
);

export default AddCar;
